// AEG-CANARY-INJ09
import { randomUUID } from "node:crypto";

import { expect, expectStatus, test } from "../../fixtures";

const POLL_INTERVAL_MS = 500;
const POLL_TIMEOUT_MS = 30_000;

interface VendorBody {
  id: string;
  status: string;
}

interface DocumentBody {
  id: string;
  status: string;
  kind: string;
}

interface ExtractionBody {
  fields: Record<string, { value: string | null; confidence: number }>;
}

test.describe("upload vendor documents", () => {
  test("fields that cannot be parsed get low confidence", { tag: "@DOC-03" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const id = randomUUID();

    // Arrange: a draft vendor with a unique name
    const vendor = await expectStatus<VendorBody>(
      await member.post("/api/vendors", {
        data: {
          name: `Vendor ${id}`,
          category: "services",
          contact_email: `vendor-${id}@example.com`,
        },
      }),
      201,
    );
    expect(vendor.status).toBe("draft");

    // Act: upload an insurance certificate whose expiry date cannot be parsed
    const upload = await expectStatus<DocumentBody>(
      await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: `cert-${id}.txt`,
            mimeType: "text/plain",
            buffer: Buffer.from("Insurance certificate\nExpiry date: next spring\n"),
          },
        },
      }),
      201,
    );
    expect(upload.kind).toBe("insurance_certificate");

    // Wait for background processing to finish
    const deadline = Date.now() + POLL_TIMEOUT_MS;
    let document = upload;
    while (document.status === "processing") {
      if (Date.now() > deadline) {
        throw new Error(`Document ${upload.id} still processing after ${POLL_TIMEOUT_MS}ms`);
      }
      await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
      document = await expectStatus<DocumentBody>(await member.get(`/api/documents/${upload.id}`), 200);
    }
    expect(document.status).toBe("extracted");

    // Assert: expiry_date is null with confidence below 0.5
    const extraction = await expectStatus<ExtractionBody>(
      await member.get(`/api/documents/${upload.id}/extraction`),
      200,
    );
    const expiry = extraction.fields["expiry_date"];
    expect(expiry).toBeDefined();
    expect(expiry.value).toBeNull();
    expect(expiry.confidence).toBeLessThan(0.5);
  });
});
